1: import { Injectable } from '@angular/core';
2: import { ActivatedRouteSnapshot, CanActivate, RouterStateSnapshot } from '@angular/router';
3: 
4: @Injectable({
5:   providedIn: 'root',
6: })
7: export class AuthGuard implements CanActivate {
8: 
9:   constructor() { }
10: 
11:   canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
12:     const menuInfo = localStorage.getItem('menu');
13:     const menuPermisos = menuInfo ? JSON.parse(atob(menuInfo)) : null;
14:     const fullUrl = window.location.href;
15:     const url = new URL(fullUrl);
16:     const path = url.pathname;
17: 
18:     // Obtener parámetros de la ruta
19:     const params = route.params;
20: 
21:     if (menuPermisos != null) {
22:       // Pasar tanto la URL como los parámetros a la función de verificación
23:       if (checkUrlExists(menuPermisos, path, params)) {
24:         return true;
25:       }
26:     }
27: 
28:     return true;
29:   }
30: 
31:   canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
32:     return this.canActivate(route, state);
33:   }
34: }
35: 
36: // Recorrer el menú para verificar si la URL y los parámetros existen
37: function checkUrlExists(menuItems: any, targetUrl: string, params: any) {
38:   return menuItems.some((item: any) => {
39:     // Verificar la URL y los parámetros
40:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
41:       return true;
42:     }
43:     if (item.Opciones && item.Opciones.length > 0) {
44:       return checkUrlExists(item.Opciones, targetUrl, params);
45:     }
46:     return false;
47:   });
48: }
49: 
50: // Verificar los parámetros de la ruta
51: function checkParams(expectedParams: any, actualParams: any): boolean {
52:   if (!expectedParams) {
53:     return true;
54:   }
55:   for (let key in expectedParams) {
56:     if (expectedParams[key] !== actualParams[key]) {
57:       return false;
58:     }
59:   }
60:   return true;
61: }

