212:   cargarCalendarioEventos(): Promise<any[]> {
213:     return new Promise((resolve, reject) => {
214:       const documento = this.obtenerDocumentoCoordinador();
215:       if (!documento || !this.codigoEventoPTD) {
216:         reject(new Error('No se pudo obtener documento o código de evento'));
217:         return;
218:       }
219:       this.sgaPlanTrabajoDocenteMidService.get(
220:         `calendario/calendario_eventos?documento=${documento}&codigo_evento=${this.codigoEventoPTD}`
221:       ).subscribe({
222:         next: (calResp: any) => {
223:           const data = calResp?.Data ?? calResp ?? [];
224:           const dataArr = Array.isArray(data) ? data : [data];
225:           const adjustedData = dataArr.map((evento: any) => {
226:             if (evento) {
227:               const adjusted = { ...evento };
228:               if (evento.FechaInicio) {
229:                 const dateInit = new Date(evento.FechaInicio);
230:                 if (!isNaN(dateInit.getTime())) {
231:                   dateInit.setHours(dateInit.getHours() + 5);
232:                   adjusted.FechaInicio = dateInit.toISOString();
233:                 }
234:               }
235:               if (evento.FechaFin) {
236:                 const dateFin = new Date(evento.FechaFin);
237:                 if (!isNaN(dateFin.getTime())) {
238:                   dateFin.setHours(dateFin.getHours() + 5);
239:                   adjusted.FechaFin = dateFin.toISOString();
240:                 }
241:               }
242:               return adjusted;
243:             }
244:             return evento;
245:           });
246:           resolve(adjustedData);
247:         },
248:         error: (err: any) => {
249:           console.warn("Error obteniendo calendario/calendario_eventos:", err);
250:           reject(err);
251:         }
252:       });
253:     });
254:   }
